import {BrowserRouter as Router, Routes, Route} from 'react-router-dom';
import HomePage from './HomePage';
import SearchPage from './SearchPage';

export const RoutesforPage = () => {
    return(
        <Router>
            <Routes>
                <Route path="/" exact>
                    <HomePage/>
                </Route>
                <Route path="/search">
                    <SearchPage/>
                </Route>
                <Route>
                    {/* not found */}
                </Route> 
            </Routes>
        </Router>
    )
}
